import{_ as a}from"./chunks/granular_media.OBtb2mKr.js";import{_ as t,o as r,c as o,a5 as s}from"./chunks/framework.DrDMl0tG.js";const g=JSON.parse('{"title":"Server Example: Granular Media","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/granular_media.md","filePath":"sections/examples/server/granular_media.md"}'),i={name:"sections/examples/server/granular_media.md"};function d(n,e,c,l,p,h){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="server-example-granular-media" tabindex="-1">Server Example: Granular Media <a class="header-anchor" href="#server-example-granular-media" aria-label="Permalink to &quot;Server Example: Granular Media&quot;">​</a></h1><p><img src="'+a+'" alt="granular_media example"></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Stands a PD-controlled ANYmal on a native granular bed created with <code>World::addGranularParticles</code> (<code>raisim::GranularSystem</code>). The grains are streamed to the viewer as instanced sphere visuals. See <a href="./../../GranularMedia.html">Granular Media</a>.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>granular_media</code>. The source is <code>examples/src/benchmark/granular_media.cpp</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/granular_media</span></span></code></pre></div><p>On Windows, run <code>granular_media.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080. Without <code>--steps</code>, the simulation starts once a viewer connects and runs until you stop it.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ul><li><code>--steps N</code> runs a fixed number of steps without waiting for a viewer, then prints the time per step and averaged contact statistics. The exit code is 2 if the bed became unstable (non-finite positions or grains faster than <code>--max-allowed-speed</code>).</li><li><code>--port=N</code> changes the server port.</li><li><code>--resolution</code>, <code>--layers</code>, <code>--radius</code>, <code>--spacing</code>, <code>--bed-length</code>, and <code>--bed-width</code> set the bed geometry; <code>--substeps</code>, <code>--stiffness</code>, <code>--damping</code>, <code>--tangential-stiffness</code>, <code>--tangential-damping</code>, <code>--friction</code>, <code>--rolling-friction</code>, and <code>--hertz</code> set the granular contact model.</li><li><code>--settle-steps</code> and <code>--robot-settle-steps</code> set how many steps run before the server starts, to let the bed and then the robot settle.</li></ul>',12)])])}const _=t(i,[["render",d]]);export{g as __pageData,_ as default};
